cat > .git/eos-android-probe.mjs <<'EOF'
// Temporary: evaluate the frame probe in the Android WebView over an adb-forwarded CDP port.
import { readFileSync } from 'node:fs';
const [, , wsUrl] = process.argv;
const ts = readFileSync('tests/rendered/html-frame-probe.ts', 'utf8');
const source = ts.slice(ts.indexOf('String.raw`') + 'String.raw`'.length, ts.lastIndexOf('`;'));
const ws = new WebSocket(wsUrl);
let id = 0;
const pending = new Map();
const requests = [];
ws.onmessage = (event) => {
  const message = JSON.parse(event.data);
  if (message.method === 'Network.requestWillBeSent') requests.push(message.params.request.url);
  if (message.id && pending.has(message.id)) pending.get(message.id)(message);
};
const cmd = (method, params = {}) => new Promise((resolve) => {
  id += 1;
  pending.set(id, resolve);
  ws.send(JSON.stringify({ id, method, params }));
});
await new Promise((resolve) => { ws.onopen = resolve; });
await cmd('Network.enable');
const evaluate = async (expression) => (await cmd('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })).result;
console.log('UA:', (await evaluate('navigator.userAgent')).result.value);
console.log('parent globals:', JSON.stringify((await evaluate(`['__TAURI_INTERNALS__','__TAURI__','__TAURI_IPC__','__TAURI_POST_MESSAGE__','__TAURI_METADATA__','ipc'].filter(k => k in window)`)).result.value));
const probe = await evaluate(source);
if (probe.exceptionDetails) console.log('EXCEPTION', JSON.stringify(probe.exceptionDetails));
for (const check of probe.result.value.checks) console.log(check.pass ? 'PASS' : 'FAIL', check.name, '-', check.detail);
// Inheritance: frame's own CSP allows https images; the app CSP must still block them.
const inherit = await evaluate(`(async () => {
  const f = document.createElement('iframe');
  f.setAttribute('sandbox', 'allow-same-origin');
  f.srcdoc = '<meta http-equiv="Content-Security-Policy" content="img-src data: https:"><img src="https://inherit-probe.invalid/a.png">';
  await new Promise(r => { f.onload = r; document.body.append(f); });
  await new Promise(r => setTimeout(r, 1500));
  const w = f.contentDocument.querySelector('img').naturalWidth;
  f.remove();
  return w;
})()`);
console.log('inheritance frame img width:', inherit.result.value);
console.log('network requests to .invalid:', JSON.stringify(requests.filter(u => u.includes('.invalid'))));
ws.close();
EOF
