+/// The first body candidates and related resources found during a bounded walk.
+#[derive(Default)]
+struct Selection<'a> {
+    plain: Option<&'a Value>,
+    html: Option<&'a Value>,
+    inline: Vec<&'a Value>,
+    attachments: bool,
+}
+
+/// Select body candidates and identify related resources before attachment filtering.
+fn select_parts<'a>(part: &'a Value, depth: usize, related: bool, out: &mut Selection<'a>) {
+    if depth > MAX_PAYLOAD_DEPTH { return; }
+    let cid = json_header_value(part, "Content-ID");
+    let disposition = json_header_value(part, "Content-Disposition");
+    let resource = related && !cid.trim().is_empty()
+        && part["body"]["attachmentId"].as_str().is_some()
+        && !disposition.trim_start().to_ascii_lowercase().starts_with("attachment");
+    if resource { out.inline.push(part); return; }
+    if is_attachment_part(part) { out.attachments = true; return; }
+    let mime = part["mimeType"].as_str().unwrap_or_default();
+    if mime.eq_ignore_ascii_case("text/plain") && out.plain.is_none() { out.plain = Some(part); }
+    if mime.eq_ignore_ascii_case("text/html") && out.html.is_none() { out.html = Some(part); }
+    if mime.to_ascii_lowercase().starts_with("multipart/") {
+        if let Some(parts) = part["parts"].as_array() {
+            if mime.eq_ignore_ascii_case("multipart/alternative") {
+                let mut group = Selection::default();
+                for child in parts { select_parts(child, depth + 1, false, &mut group); }
+                if group.plain.is_some() && group.html.is_some() && (out.plain.is_none() || out.html.is_none()) {
+                    out.plain = group.plain; out.html = group.html;
+                } else {
+                    if out.plain.is_none() { out.plain = group.plain; }
+                    if out.html.is_none() { out.html = group.html; }
                 }
+                out.inline.extend(group.inline); out.attachments |= group.attachments;
+            } else {
+                for child in parts { select_parts(child, depth + 1, mime.eq_ignore_ascii_case("multipart/related"), out); }
             }
         }
     }
+}
+
+/// Validate fetchable inline image metadata.
+fn inline_part(message_id: &str, part: &Value) -> Option<InlinePart> {
+    let id = part["body"]["attachmentId"].as_str()?;
+    let size = part["body"]["size"].as_u64()?;
+    let mime = part["mimeType"].as_str()?.to_ascii_lowercase();
+    let cid = json_header_value(part, "Content-ID");
+    let cid = cid.trim().trim_start_matches('<').trim_end_matches('>');
+    if !crate::attachments::valid_id(message_id) || cid.is_empty() || cid.len() > 998 || cid.chars().any(|c| c.is_control() || c.is_whitespace())
+        || !crate::attachments::valid_attachment_id(id) || !crate::attachments::valid_mime(&mime)
+        || !matches!(mime.as_str(), "image/png" | "image/jpeg" | "image/gif" | "image/webp")
+        || size > 2 * 1024 * 1024 { return None; }
+    Some(InlinePart { message_id: message_id.into(), content_id: cid.into(), attachment_id: id.into(), mime_type: mime, size: size as u32 })
+}
+
+/// Decode Gmail's wrapper and the declared charset strictly for either body type.
+fn decode_part(part: &Value, html: bool) -> Result<String, String> {
+    let data = part["body"]["data"].as_str().ok_or("missing body")?;
+    let bytes = b64url_decode(data).map_err(|_| "invalid body")?;
+    if bytes.len() > MAX_PART_BODY_BYTES { return Err("body too large".into()); }
+    let raw = part_raw(part, &bytes);
+    let parsed = mailparse::parse_mail(&raw).map_err(|_| "invalid MIME")?;
+    let bytes = parsed.get_body_raw().map_err(|_| "invalid body")?;
+    let content_type = json_header_value(part, "Content-Type");
+    let has_charset = content_type.split(';').skip(1).any(|p| p.trim().split('=').next().is_some_and(|n| n.trim().eq_ignore_ascii_case("charset")));
+    if html && !has_charset {
+        if let Ok(text) = std::str::from_utf8(&bytes) { return Ok(text.replace("\r\n", "\n").replace('\r', "\n")); }
+        let label = sniff_charset(&bytes).ok_or("missing charset")?;
+        return decode_charset(&bytes, &label);
+    }
+    decode_charset(&bytes, &parsed.ctype.charset)
+}
+
+/// Read a charset declaration from a meta tag in the first 1024 bytes.
+fn sniff_charset(bytes: &[u8]) -> Option<String> {
+    let prefix = String::from_utf8_lossy(&bytes[..bytes.len().min(1024)]).to_ascii_lowercase();
+    for tag in prefix.split('<').skip(1) {
+        let tag = tag.split('>').next()?;
+        if !tag.trim_start().starts_with("meta") { continue; }
+        if let Some(pos) = tag.find("charset") {
+            let rest = tag[pos + 7..].trim_start();
+            let rest = rest.strip_prefix('=')?.trim_start().trim_start_matches(['\"', '\'']);
+            let label: String = rest.chars().take_while(|c| c.is_ascii_alphanumeric() || matches!(c, '-' | '_' | '.')).collect();
+            if !label.is_empty() { return Some(label); }
+        }
+    }
     None
 }

+fn decode_charset(bytes: &[u8], label: &str) -> Result<String, String> {
+    let charset = charset::Charset::for_label(label.as_bytes()).ok_or("unsupported charset")?;
+    let (decoded, _, errors) = charset.decode(bytes);
+    if errors { return Err("lossy charset".into()); }
+    Ok(decoded.replace("\r\n", "\n").replace('\r', "\n"))
+}
+
+/// Derive unwrapped, undecorated searchable text, retaining link destinations.
+fn html_to_text(html: &str) -> Option<String> {
+    let text = html2text::config::plain_no_decorate().link_footnotes(true).string_from_read(html.as_bytes(), 10_000).ok()?;
+    Some(text.replace("\r\n", "\n").replace('\r', "\n").chars().take(MAX_MESSAGE_TEXT_CHARS).collect())
+}
