      id: 21,
      subject: 'Logo proof',
      from: addr('Lee Fixture', 'lee@fixture.example'),
      bodyText: 'Here is the logo proof.',
      html: cidHtml,
      inlineImage: { contentId: 'logo@fixture.example', attachmentId: 'fixture-logo' },
    },
    {
      id: 22,
      subject: 'Re: Venue options',
      from: ana,
      bodyText: replyText,
      html: replyHtml,
    },
