import createDOMPurify from 'dompurify';
import { filterCss, filterStyleAttribute } from './css-filter';

export interface SanitizedMail {
  styles: string;
  body: string;
  remoteBlocked: number;
  cidReferences: string[];
  hasOwnColours: boolean;
  hasTrailingQuote: boolean;
}

export function sanitizeMailHtml(html: string, options: { remoteImages: boolean }): SanitizedMail {
  const purifier = createDOMPurify(window);
  const document = purifier.sanitize(html, {
    WHOLE_DOCUMENT: true,
    RETURN_DOM: true,
    USE_PROFILES: { html: true },
    ALLOW_DATA_ATTR: false,
    SANITIZE_DOM: true,
    FORBID_TAGS: ['script', 'noscript', 'iframe', 'frame', 'frameset', 'object', 'embed', 'applet', 'form', 'input', 'button', 'select', 'textarea', 'option', 'link', 'meta', 'base', 'audio', 'video', 'source', 'track', 'portal', 'template', 'svg', 'math', 'title'],
    FORBID_CONTENTS: ['script', 'noscript', 'iframe', 'frame', 'frameset', 'object', 'embed', 'applet', 'form', 'select', 'textarea', 'option', 'audio', 'video', 'portal', 'template', 'svg', 'math', 'title'],
    ADD_TAGS: ['style'],
  }) as unknown as HTMLElement;
  const body = document.querySelector('body');
  const result: SanitizedMail = { styles: '', body: '', remoteBlocked: 0, cidReferences: [], hasOwnColours: false, hasTrailingQuote: false };
  if (!body) return result;
  const colours = /(?:^|[;{])\s*(?:color|background|background-color)\s*:/i;
  for (const style of document.querySelectorAll('style')) {
    const filtered = filterCss(style.textContent ?? '', options);
    result.styles += filtered.css + '\n';
    result.remoteBlocked += filtered.blockedRemote;
    if (colours.test(filtered.css)) result.hasOwnColours = true;
    style.remove();
  }
  const candidates = body.querySelectorAll('.gmail_quote, blockquote[type="cite"], #divRplyFwdMsg, #appendonsend, .yahoo_quoted, .protonmail_quote');
  for (const candidate of candidates) {
    const special = candidate.id === 'divRplyFwdMsg' || candidate.id === 'appendonsend';
    let node: Node | null = candidate;
    let visible = false;
    while (node && node !== body) {
      let sibling = node.nextSibling;
      while (sibling) {
        if (!special || node !== candidate) {
          if ((sibling.textContent ?? '').trim() || (sibling instanceof Element && (sibling.matches('img') || sibling.querySelector('img')))) visible = true;
        }
        sibling = sibling.nextSibling;
      }
      node = node.parentNode;
    }
    if (!visible) {
      candidate.setAttribute('data-eos-quote', 'trailing');
      if (special) for (let sibling = candidate.nextElementSibling; sibling; sibling = sibling.nextElementSibling) sibling.setAttribute('data-eos-quote', 'trailing');
      result.hasTrailingQuote = true;
      break;
    }
  }
  const image = (element: Element, attribute: string) => {
    const value = element.getAttribute(attribute)?.trim();
    if (!value) return;
    element.removeAttribute(attribute);
    if (/^cid:/i.test(value)) {
      try {
        const cid = decodeURIComponent(value.slice(4));
        if (cid) { element.setAttribute('data-eos-cid', cid); if (!result.cidReferences.includes(cid)) result.cidReferences.push(cid); }
      } catch { /* Invalid encoding is discarded. */ }
    } else if (/^data:image\/(png|jpeg|gif|webp);base64,[a-z0-9+/=]+$/i.test(value)) element.setAttribute(attribute, value);
    else {
      try {
        const url = new URL(value);
        if (url.protocol === 'https:') {
          if (options.remoteImages) element.setAttribute(attribute, url.href);
          else { element.setAttribute(attribute === 'background' ? 'data-eos-background' : 'data-eos-src', url.href); result.remoteBlocked++; }
        }
      } catch { /* Relative and malformed URLs are discarded. */ }
    }
  };
  for (const element of [body, ...body.querySelectorAll('*')]) {
    for (const attribute of [...element.attributes]) {
      const name = attribute.name.toLowerCase();
      if (name.startsWith('on') || ['srcset', 'ping', 'formaction', 'xlink:href', 'action', 'target', 'poster', 'cite', 'longdesc', 'lowsrc', 'dynsrc'].includes(name)) element.removeAttribute(attribute.name);
      if (name === 'href') {
        element.removeAttribute(attribute.name);
        if (element.tagName === 'A') {
          try {
            const url = new URL(attribute.value);
            if (['http:', 'https:', 'mailto:'].includes(url.protocol)) { element.setAttribute('data-eos-href', url.href); element.setAttribute('role', 'link'); element.setAttribute('tabindex', '0'); }
          } catch { /* Relative and malformed links are discarded. */ }
        }
      }
    }
    if (element.tagName === 'IMG') image(element, 'src');
    else element.removeAttribute('src');
    if (['TABLE', 'TD', 'TH', 'TR', 'BODY'].includes(element.tagName)) image(element, 'background');
    else element.removeAttribute('background');
    if (element.hasAttribute('style')) {
      const filtered = filterStyleAttribute(element.getAttribute('style') ?? '', options);
      result.remoteBlocked += filtered.blockedRemote;
      if (filtered.css) { element.setAttribute('style', filtered.css); if (colours.test(filtered.css)) result.hasOwnColours = true; }
      else element.removeAttribute('style');
    }
    if (['bgcolor', 'background', 'data-eos-background'].some(name => element.hasAttribute(name)) || (element.tagName === 'FONT' && element.hasAttribute('color')) || (element === body && (element.hasAttribute('text') || element.hasAttribute('link')))) result.hasOwnColours = true;
  }
  const wrapper = window.document.createElement('div');
  wrapper.className = 'eos-mail-body';
  for (const name of ['bgcolor', 'text', 'link', 'style', 'background', 'data-eos-background', 'data-eos-cid']) {
    if (body.hasAttribute(name)) wrapper.setAttribute(name, body.getAttribute(name) ?? '');
  }
  wrapper.innerHTML = body.innerHTML;
  result.body = wrapper.outerHTML;
  return result;
}

