import type { SanitizedMail } from './sanitize';

/** No scripts, forms, popups, top-navigation, modals or downloads (ADR 0006 decision 9). */
export const FRAME_SANDBOX = 'allow-same-origin';

/** Policy applied before any mail content is parsed. */
export function frameCsp(remoteImages: boolean): string {
  return `default-src 'none'; script-src 'none'; style-src 'unsafe-inline'; img-src data:${remoteImages ? ' https:' : ''}; font-src data:; form-action 'none'`;
}

export interface FrameTheme {
  mode: 'paper' | 'adaptive';
  fontFamily: string;
  fontSize: string;
  lineHeight: string;
  textColour: string;
  linkColour: string;
}

/** Builds the isolated document using only validated values in our base CSS. */
export function buildFrameDocument(mail: SanitizedMail, options: { remoteImages: boolean; theme: FrameTheme; quoteOpen: boolean }): string {
  const { theme } = options;
  const safe = (value: string, pattern: RegExp, fallback: string) => pattern.test(value) ? value : fallback;
  const family = safe(theme.fontFamily, /^[a-zA-Z0-9 ,'"-]+$/, 'sans-serif');
  const size = safe(theme.fontSize, /^\d+(?:\.\d+)?(?:px|rem|em)$/, '16px');
  const leading = safe(theme.lineHeight, /^\d+(?:\.\d+)?(?:px|rem|em)$/, '24px');
  const colour = /^#(?:[a-fA-F0-9]{3,4}|[a-fA-F0-9]{6}|[a-fA-F0-9]{8})$|^rgba?\([\d\s,.]+\)$/;
  const text = safe(theme.textColour, colour, '#ffffff');
  const link = safe(theme.linkColour, colour, '#bba5ed');
  const paper = theme.mode === 'paper';
  const base = `html { color-scheme: ${paper ? 'light' : 'dark'}; background: ${paper ? '#ffffff' : 'transparent'}; color: ${paper ? '#1f1f1f' : text}; ${paper ? 'padding: 16px;' : `font-family: ${family}; font-size: ${size}; line-height: ${leading};`} }
body { margin: 0; overflow-wrap: anywhere; }
img { max-width: 100%; height: auto; }
table { max-width: none; }
[data-eos-href] { cursor: pointer; }
${paper ? '' : `[data-eos-href] { color: ${link}; text-decoration: underline; }`}
html:not(.eos-quote-open) [data-eos-quote="trailing"] { display: none !important; }`;
  return `<!doctype html><html class="${options.quoteOpen ? 'eos-quote-open' : ''}"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="${frameCsp(options.remoteImages)}"><style>${base}</style><style>${mail.styles}</style></head><body>${mail.body}</body></html>`;
}

/** Scales wide content to fit, retaining a minimum readable zoom. */
export function fitZoom(contentWidth: number, available: number): number {
  return contentWidth <= available ? 1 : Math.max(0.5, available / contentWidth);
}
<script lang="ts">
import type { MessageHtmlBody } from '../lib/ipc/generated';
import type { SanitizedMail } from '../lib/html-mail/sanitize';

// Keep only the last 20 sanitized variants, including their inline metadata.
const cache = new Map<string, { mail: SanitizedMail; body: MessageHtmlBody }>();
</script>

<script setup lang="ts">
import { onBeforeUnmount, ref, watch } from 'vue';
import type { ConversationRef, MailClient } from '../lib/ipc/client';
import { sanitizeMailHtml } from '../lib/html-mail/sanitize';
import { frameHasNativeGlobals } from '../lib/html-mail/frame-guard';
import { buildFrameDocument, fitZoom, FRAME_SANDBOX, type FrameTheme } from '../lib/html-mail/frame-document';

const props = defineProps<{ client: MailClient; conversation: ConversationRef; messageId: string; title: string; remoteImages: boolean; quoteOpen: boolean; theme: FrameTheme }>();
const emit = defineEmits<{ link: [url: string, text: string]; state: [value: { remoteBlocked: number; hasTrailingQuote: boolean }]; fallback: [reason: 'unavailable' | 'error'] }>();
const frame = ref<HTMLIFrameElement | null>(null);
const result = ref<{ mail: SanitizedMail; body: MessageHtmlBody } | null>(null);
const unavailable = ref(false);
let generation = 0;
let cleanup = () => {};
let fetchedKey = '';
let fetched: Promise<MessageHtmlBody> | null = null;

watch(() => [props.conversation.accountId, props.conversation.conversationId, props.messageId, props.remoteImages] as const, async ([account, conversation, message, remote]) => {
  const current = ++generation;
  cleanup();
  result.value = null;
  unavailable.value = false;
  const identity = JSON.stringify([account, conversation, message]);
  const key = JSON.stringify([account, conversation, message, remote]);
  try {
    let entry = cache.get(key);
    if (!entry) {
      if (fetchedKey !== identity || !fetched) {
        fetchedKey = identity;
        fetched = props.client.getMessageHtml({ accountId: account, conversationId: conversation }, message);
      }
      const body = await fetched;
      entry = { body, mail: sanitizeMailHtml(body.html, { remoteImages: remote }) };
      cache.set(key, entry);
      if (cache.size > 20) cache.delete(cache.keys().next().value!);
    } else {
      cache.delete(key);
      cache.set(key, entry);
    }
    if (current === generation) result.value = entry;
  } catch {
    if (current === generation) emit('fallback', 'error');
  }
}, { immediate: true });

const srcdoc = ref('');
watch([result, () => props.theme], () => {
  srcdoc.value = result.value ? buildFrameDocument(result.value.mail, { remoteImages: props.remoteImages, theme: props.theme, quoteOpen: props.quoteOpen }) : '';
}, { deep: true });
watch(() => props.quoteOpen, (open) => {
  frame.value?.contentDocument?.documentElement.classList.toggle('eos-quote-open', open);
  requestAnimationFrame(() => fit());
});

let fit = () => {};
function onLoad() {
  const element = frame.value;
  const entry = result.value;
  if (!element || !entry) return;
  cleanup();
  if (frameHasNativeGlobals(element)) {
    unavailable.value = true;
    emit('fallback', 'unavailable');
    return;
  }
  const doc = element.contentDocument;
  if (!doc) return;
  const root = doc.documentElement;
  let active = true;
  let raf = 0;
  fit = () => {
    if (!active || !element.clientWidth) return;
    root.style.zoom = '1';
    root.style.overflowX = 'hidden';
    const width = root.scrollWidth;
    const zoom = fitZoom(width, element.clientWidth);
    root.style.zoom = String(zoom);
    root.style.overflowX = width * zoom > element.clientWidth ? 'auto' : 'hidden';
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => {
      // Chrome reports scrollHeight in unzoomed CSS pixels; zoom scales the rendered height.
      if (active) element.style.height = `${Math.ceil(root.scrollHeight * zoom)}px`;
    });
  };
  const activate = (target: EventTarget | null) => {
    const link = target && (target as Node).nodeType === 1 ? (target as Element).closest('[data-eos-href]') : null;
    const url = link?.getAttribute('data-eos-href');
    if (url) emit('link', url, (link?.textContent ?? '').trim().slice(0, 200));
  };
  const click = (event: MouseEvent) => { event.preventDefault(); activate(event.target); };
  const keydown = (event: KeyboardEvent) => {
    const target = event.target as Element | null;
    if ((event.key === 'Enter' || event.key === ' ') && target?.closest('[data-eos-href]')) {
      event.preventDefault();
      activate(target);
      return;
    }
    if ((event.shiftKey && /^(ArrowUp|ArrowDown|ArrowLeft|ArrowRight|Home|End|PageUp|PageDown)$/.test(event.key)) || ((event.ctrlKey || event.metaKey) && /^[ac]$/i.test(event.key))) return;
    const forwarded = new KeyboardEvent('keydown', { key: event.key, code: event.code, shiftKey: event.shiftKey, ctrlKey: event.ctrlKey, altKey: event.altKey, metaKey: event.metaKey, repeat: event.repeat, bubbles: true, cancelable: true });
    if (!element.dispatchEvent(forwarded)) event.preventDefault();
  };
  doc.addEventListener('click', click, true);
  doc.addEventListener('keydown', keydown, true);
  const images = [...doc.querySelectorAll('img')];
  for (const img of images) {
    img.addEventListener('load', fit);
    const inline = entry.body.inlineImages.find((item) => item.contentId === img.dataset.eosCid);
    if (inline) void props.client.getInlineImage(props.conversation, props.messageId, inline.attachmentId).then((data) => {
      if (active) img.src = `data:${data.mimeType};base64,${data.base64}`;
    }).catch(() => {});
  }
  const observer = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(fit);
  if (element.parentElement) observer?.observe(element.parentElement);
  cleanup = () => {
    active = false;
    cancelAnimationFrame(raf);
    observer?.disconnect();
    doc.removeEventListener('click', click, true);
    doc.removeEventListener('keydown', keydown, true);
    for (const img of images) img.removeEventListener('load', fit);
    fit = () => {};
  };
  fit();
  emit('state', { remoteBlocked: entry.mail.remoteBlocked, hasTrailingQuote: entry.mail.hasTrailingQuote });
}
onBeforeUnmount(() => { generation++; cleanup(); });
</script>

<template>
  <iframe v-if="result && !unavailable" ref="frame" :sandbox="FRAME_SANDBOX" :srcdoc="srcdoc" :title="title" class="html-message-frame" :class="{ paper: theme.mode === 'paper' }" scrolling="no" referrerpolicy="no-referrer" @load="onLoad" />
</template>

<style scoped>
.html-message-frame { display: block; width: 100%; border: 0; }
.html-message-frame.paper { border-radius: 8px; background: #ffffff; }
</style>

