import { createBrowserFakeMailClient } from './ipc/browser-fake';
import type { MailClient } from './ipc/client';

/** Browser-only ownership descriptor. Not a native account/profile selector. */
export interface FixtureWorkspace {
  readonly accountId: string;
  readonly emailAddress: string;
  readonly client: MailClient;
}

export function createFixtureWorkspaces(): readonly FixtureWorkspace[] {
  return [
    { accountId: 'fixture-account', emailAddress: 'you@fixture.emailos' },
    { accountId: 'fixture-account-two', emailAddress: 'you@second.example.test' },
  ].map((identity) => Object.freeze({
    ...identity,
    client: createBrowserFakeMailClient(undefined, identity),
  }));
}
import './assets/mobile/notices.css';
import './assets/mobile/compose.css';
import './assets/mobile/pages.css';
import { isTauriRuntime, selectMailClient } from './lib/ipc';
import FixtureWorkspaces from './FixtureWorkspaces.vue';
import { createFixtureWorkspaces } from './lib/fixture-workspaces';

if (isTauriRuntime()) {
  const { client, mode } = selectMailClient();
  createApp(StartupRoot, { client, mode }).mount('#app');
} else {
  createApp(FixtureWorkspaces, { sessions: createFixtureWorkspaces() }).mount('#app');
}
import './assets/mobile/tokens.css';
import './assets/mobile/shell.css';
tests/layout/mobile-shell.rendered.test.ts
tests/discovery/discovery.rendered.test.ts
src/FixtureWorkspaces.vue
src/lib/fixture-workspaces.ts
src/assets/style.css
